class Shape:
    def area(self):
        raise NotImplementedError("Subclasses must implement area()")

    def describe(self):
        return f"{type(self).__name__} area={self.area()}"


class Circle(Shape):
    """
    A circle defined by its radius.
    """
    def __init__(self, radius):
        self.radius = radius

    def area(self):
        import math
        return math.pi * self.radius ** 2


class Rectangle(Shape):
    """
    A rectangle defined by its width and height.
    """
    def __init__(self, width, height):
        self.width = width
        self.height = height

    def area(self):
        return self.width * self.height


class Triangle(Shape):
    """
    A triangle defined by its base and height.
    """
    def __init__(self, base, height):
        self.base = base
        self.height = height

    def area(self):
        return 0.5 * self.base * self.height


def total_area(shapes):
    return sum(shape.area() for shape in shapes)

import React, { useRef, useEffect, useState } from 'react';

interface ReasoningFrame {
  id: string;
  title: string;
  body: string;
  tokens: number;
}

interface ReasoningPanelProps {
  frames: ReasoningFrame[];
  isStreaming: boolean;
  onSeek?: (id: string) => void;
}

const ReasoningPanel: React.FC<ReasoningPanelProps> = ({ frames, isStreaming, onSeek }) => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const isUserScrolledUp = useRef<boolean>(false);
  const [totalTokens, setTotalTokens] = useState<number>(0);

  useEffect(() => {
    const sum: number = frames.reduce((acc: number, frame: ReasoningFrame) => acc + frame.tokens, 0);
    setTotalTokens(sum);
  }, [frames]);

  useEffect(() => {
    const container: HTMLDivElement | null = containerRef.current;
    if (container && !isUserScrolledUp.current) {
      container.scrollTop = container.scrollHeight;
    }
  }, [frames.length]);

  const handleScroll: React.UIEventHandler<HTMLDivElement> = () => {
    const container: HTMLDivElement | null = containerRef.current;
    if (container) {
      const isAtBottom: boolean = container.scrollHeight - container.scrollTop - container.clientHeight < 5;
      isUserScrolledUp.current = !isAtBottom;
    }
  };

  const handleFrameClick: (id: string) => void = (id: string) => {
    if (onSeek) {
      onSeek(id);
    }
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%', fontFamily: 'sans-serif' }}>
      <div style={{ padding: '8px 16px', borderBottom: '1px solid #e0e0e0', fontSize: '14px', fontWeight: 'bold' }}>
        Total Tokens: {totalTokens}
      </div>
      <div
        ref={containerRef}
        onScroll={handleScroll}
        style={{
          flex: 1,
          overflowY: 'auto',
          padding: '16px',
          display: 'flex',
          flexDirection: 'column',
          gap: '12px',
        }}
      >
        {frames.map((frame: ReasoningFrame) => (
          <div
            key={frame.id}
            onClick={() => handleFrameClick(frame.id)}
            style={{
              border: '1px solid #d0d0d0',
              borderRadius: '4px',
              padding: '12px',
              cursor: onSeek ? 'pointer' : 'default',
              backgroundColor: '#fafafa',
            }}
          >
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' }}>
              <span style={{ fontWeight: 'bold', fontSize: '14px' }}>{frame.title}</span>
              <span style={{ fontSize: '12px', color: '#666' }}>{frame.tokens} tokens</span>
            </div>
            <div style={{ fontSize: '13px', color: '#333', whiteSpace: 'pre-wrap' }}>{frame.body}</div>
          </div>
        ))}
        {isStreaming && (
          <div style={{ textAlign: 'center', color: '#888', fontSize: '12px', padding: '8px' }}>
            Streaming...
          </div>
        )}
      </div>
    </div>
  );
};

