import { useRef, useEffect, useState, useCallback } from 'react';

interface ReasoningFrame {
  id: string;
  title: string;
  body: string;
  tokens: number;
}

interface ReasoningPanelProps {
  frames: ReasoningFrame[];
  isStreaming: boolean;
  onSeek?: (id: string) => void;
}

const ReasoningPanel: React.FC<ReasoningPanelProps> = ({ frames, isStreaming, onSeek }) => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const isUserScrolledRef = useRef<boolean>(false);
  const [isUserScrolled, setIsUserScrolled] = useState<boolean>(false);

  const totalTokens: number = frames.reduce<number>(
    (acc: number, frame: ReasoningFrame): number => acc + frame.tokens,
    0
  );

  const handleScroll: React.UIEventHandler<HTMLDivElement> = useCallback(
    (event: React.UIEvent<HTMLDivElement>): void => {
      const element: HTMLDivElement = event.currentTarget;
      const isAtBottom: boolean =
        element.scrollHeight - element.scrollTop - element.clientHeight < 5;

      if (isAtBottom) {
        isUserScrolledRef.current = false;
        setIsUserScrolled(false);
      } else {
        isUserScrolledRef.current = true;
        setIsUserScrolled(true);
      }
    },
    []
  );

  const handleSeek: (id: string) => void = useCallback(
    (id: string): void => {
      if (onSeek) {
        onSeek(id);
      }
    },
    [onSeek]
  );

  useEffect<void>(() => {
    const container: HTMLDivElement | null = containerRef.current;
    if (container && !isUserScrolledRef.current) {
      container.scrollTo({
        top: container.scrollHeight,
        behavior: 'smooth',
      });
    }
  }, [frames.length]);

  const renderFrame: (frame: ReasoningFrame) => React.ReactNode = (
    frame: ReasoningFrame
  ): React.ReactNode => {
    return (
      <div
        key={frame.id}
        onClick={() => handleSeek(frame.id)}
        style={{
          padding: '8px',
          borderBottom: '1px solid #e0e0e0',
          cursor: onSeek ? 'pointer' : 'default',
        }}
      >
        <div style={{ fontWeight: 'bold' }}>{frame.title}</div>
        <div style={{ color: '#666', fontSize: '0.9em' }}>{frame.body}</div>
        <div style={{ color: '#999', fontSize: '0.8em', marginTop: '4px' }}>
          Tokens: {frame.tokens}
        </div>
      </div>
    );
  };

  return (
    <div>
      <div style={{ padding: '8px', borderBottom: '2px solid #ccc' }}>
        Total Tokens: {totalTokens}
        {isStreaming && !isUserScrolled && (
          <span style={{ marginLeft: '10px', color: 'blue' }}>Streaming...</span>
        )}
      </div>
      <div
        ref={containerRef}
        onScroll={handleScroll}
        style={{
          height: '300px',
          overflowY: 'auto',
          border: '1px solid #ccc',
        }}
      >
        {frames.length === 0 ? (
          <div style={{ padding: '16px', color: '#999' }}>No reasoning frames.</div>
        ) : (
          frames.map<React.ReactNode>((frame: ReasoningFrame): React.ReactNode =>
            renderFrame(frame)
          )
        )}
      </div>
    </div>
  );
};

