import React, { useRef, useEffect } from 'react';

interface ReasoningFrame {
  id: string;
  title: string;
  body: string;
  tokens: number;
}

interface ReasoningPanelProps {
  frames: ReasoningFrame[];
  isStreaming: boolean;
  onSeek?: (id: string) => void;
}

const ReasoningPanel: React.FC<ReasoningPanelProps> = ({ frames, isStreaming, onSeek }) => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const isUserScrolled = useRef<boolean>(false);

  useEffect(() => {
    if (!isUserScrolled.current && isStreaming && containerRef.current) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight;
    }
  }, [frames.length, isStreaming]);

  const handleScroll = (): void => {
    const container = containerRef.current;
    if (!container) return;

    const scrollHeight: number = container.scrollHeight;
    const scrollTop: number = container.scrollTop;
    const clientHeight: number = container.clientHeight;

    // Check if user is near the bottom (within 5px)
    const isNearBottom: boolean = scrollTop + clientHeight >= scrollHeight - 5;

    if (!isNearBottom) {
      isUserScrolled.current = true;
    } else {
      isUserScrolled.current = false;
    }
  };

  const totalTokens: number = frames.reduce((sum: number, frame: ReasoningFrame) => sum + frame.tokens, 0);

  const handleFrameClick = (id: string): void => {
    if (onSeek) {
      onSeek(id);
    }
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%', maxHeight: '400px' }}>
      <div style={{ padding: '10px', borderBottom: '1px solid #ccc', fontWeight: 'bold' }}>
        Total Tokens: {totalTokens}
      </div>
      <div
        ref={containerRef}
        onScroll={handleScroll}
        style={{ overflowY: 'auto', flex: 1, padding: '10px' }}
      >
        {frames.map((frame: ReasoningFrame, index: number) => (
          <div
            key={frame.id}
            onClick={() => handleFrameClick(frame.id)}
            style={{
              marginBottom: '10px',
              padding: '8px',
              border: '1px solid #eee',
              borderRadius: '4px',
              cursor: onSeek ? 'pointer' : 'default',
              background: isStreaming && index === frames.length - 1 ? '#f9f9f9' : '#ffffff'
            }}
          >
            <div style={{ fontWeight: 'bold', marginBottom: '4px' }}>
              {frame.title} <span style={{ fontWeight: 'normal', color: '#666' }}>({frame.tokens} tokens)</span>
            </div>
            <div style={{ fontSize: '14px', color: '#333' }}>
              {frame.body}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

